import test from 'node:test';
import assert from 'node:assert/strict';
import { isWeekend } from '../src/calendar.js';

test('Saturday is a weekend and Monday is not', () => {
  assert.equal(isWeekend(new Date('2026-10-17T00:00:00Z')), true);
  assert.equal(isWeekend(new Date('2026-10-19T00:00:00Z')), false);
});

